import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const b=JSON.parse('{"title":"Topbar","description":"","frontmatter":{},"headers":[],"relativePath":"components/topbar.md","filePath":"components/topbar.md"}'),r={name:"components/topbar.md"};function n(i,e,s,c,h,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="topbar" tabindex="-1">Topbar <a class="header-anchor" href="#topbar" aria-label="Permalink to &quot;Topbar&quot;">​</a></h1><p>Topbar is the toolbar at the top of the screen: the brand, the current place, a title and the actions.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it once per screen, above everything else. The application passes what it shows: its name in <code>brand</code> (a link with <code>brandHref</code>, or the trigger of its menu with <code>brandMenu</code>), the trail to the current place in <code>crumbs</code>, the name of the open document in <code>center</code> (an <a href="./inline-edit">InlineEdit</a> when it can be renamed), who else is here in <code>presence</code> (a <a href="./presence">Presence</a>), and its actions in <code>end</code>. <code>lead</code> holds a button before the brand, such as the one that opens a drawer on a narrow screen. The head of a panel or a modal is a <a href="./toolbar">Toolbar</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>brand</code></td><td></td><td>The application&#39;s name; without it, no brand</td></tr><tr><td><code>brandHref</code></td><td></td><td>Draws the brand as a link, with the same look</td></tr><tr><td><code>brandTarget</code></td><td></td><td><code>_blank</code> opens the brand&#39;s link in another tab</td></tr><tr><td><code>brandMenu</code></td><td></td><td>The brand opens a menu: its MenuItems (a snippet)</td></tr><tr><td><code>menu</code></td><td></td><td>The brand opens a menu drawn from a model (<code>MenuModel[]</code>)</td></tr><tr><td><code>onmenu</code></td><td></td><td>Called with the id of the chosen item of <code>menu</code></td></tr><tr><td><code>brandLabel</code></td><td></td><td>The name of the menu&#39;s trigger</td></tr><tr><td><code>crumbs</code></td><td></td><td>The trail to the current place, <code>{ label, href?, onclick? }[]</code></td></tr><tr><td><code>crumbsLabel</code></td><td></td><td>The name of the trail</td></tr><tr><td><code>lead</code></td><td></td><td>Before the brand (a snippet)</td></tr><tr><td><code>start</code></td><td></td><td>After the brand and the crumbs (a snippet)</td></tr><tr><td><code>center</code></td><td></td><td>A title or an inline edit in the centre (a snippet)</td></tr><tr><td><code>presence</code></td><td></td><td>Who else is here, before the actions (a snippet)</td></tr><tr><td><code>end</code></td><td></td><td>The actions at the right end (a snippet)</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The height is a <a href="./toolbar">Toolbar</a>&#39;s, the surface the panel color, with a strong line along the bottom; pad-md at the sides and small buttons inside. The brand is h2, trimmed to its ink, with its letters drawn a little closer (<code>--kata-topbar-brand-tracking</code>, <code>-0.01em</code> unless the page sets it); with <code>brandMenu</code> it is a button without a line, with a chevron, that opens a <a href="./dropdown">Dropdown</a> menu below it (the snippet receives <code>close</code>). <code>menu</code> opens the same Dropdown with a <a href="./../workbench/menu-list">MenuList</a> of the model, as an <a href="./../workbench/app-menu">AppMenu</a> does. The start keeps its size except the crumbs, which shrink; the centre takes the rest of the width and shrinks first, and what is in it clips its own text. The end holds <code>presence</code> and <code>end</code> as two groups gap-md apart; inside a group, icon buttons sit side by side. Nothing wraps and the places never overlap. Below 24rem the brand is hidden and the buttons stay.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/topbar/" title="Topbar" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/topbar/" target="_blank" rel="noopener">Topbar</a></figcaption></figure>',10)])])}const m=t(r,[["render",n]]);export{b as __pageData,m as default};
